body.script:
import { renderPyramid, formatPopulation, buildLegendHTML } from './plot.js';

const DEFAULTS = {
  slYear: '2024', slTfr: '1.5',
  slMortMale: '1.00', slMortFemale: '1.00', slMigration: '1',
  slRetireMale: '63', slRetireFemale: '63', slUnemployment: '5.0',
  slWomenActivity: '75', slPartTime: '4', slDisability: '1.0', slStudyShift: '0'
};

// ─── State ───────────────────────────────────────────────────────────────────
let snapshots = null, stateSnapshots = null, ratioSeries = null, anchorData = null;
const startYear = 2024, endYear = 2150;
const hiddenStates = new Set();

// ─── DOM refs ────────────────────────────────────────────────────────────────
const $ = id => document.getElementById(id);

const sliders = {
  year: $('slYear'), tfr: $('slTfr'),
  mortMale: $('slMortMale'), mortFemale: $('slMortFemale'), migration: $('slMigration'),
  retireMale: $('slRetireMale'), retireFemale: $('slRetireFemale'),
  unemployment: $('slUnemployment'), womenActivity: $('slWomenActivity'),
  partTime: $('slPartTime'), disability: $('slDisability'), studyShift: $('slStudyShift')
};

const vals = {
  tfr: $('valTfr'),
  mortMale: $('valMortMale'), mortFemale: $('valMortFemale'), migration: $('valMigration'),
  retireMale: $('valRetireMale'), retireFemale: $('valRetireFemale'),
  unemployment: $('valUnemployment'), womenActivity: $('valWomenActivity'),
  partTime: $('valPartTime'), disability: $('valDisability'), studyShift: $('valStudyShift')
};

const statEls = {
  totalPop: $('statTotalPop'), malePop: $('statMalePop'), femalePop: $('statFemalePop'),
  medianAge: $('statMedianAge'), payers: $('statPayers'), payersDetail: $('statPayersDetail'),
  recipients: $('statRecipients'), recipientsDetail: $('statRecipientsDetail'),
  children: $('statChildren'), working: $('statWorking'), seniors: $('statSeniors')
};

const ratioEl = $('ratioValue');
const ratioDetailEl = $('ratioDetail');
const pyramidContainer = $('pyramidContainer');
const yearDisplay = $('yearDisplay');
const legendContainer = $('legendContainer');

// ─── Worker ──────────────────────────────────────────────────────────────────
const worker = new Worker('worker.js', { type: 'module' });

worker.onmessage = e => {
  if (e.data.type === 'result') {
    snapshots = e.data.snapshots;
    stateSnapshots = e.data.stateSnapshots;
    ratioSeries = e.data.ratioSeries;
    renderCurrentYear();
  } else if (e.data.type === 'error') {
    console.error('Simulation error:', e.data.message);
  }
};

// ─── Params ──────────────────────────────────────────────────────────────────
function getDemoParams() {
  return {
    tfr: +sliders.tfr.value, sexRatio: 0.512,
    mortMale: +sliders.mortMale.value, mortFemale: +sliders.mortFemale.value,
    migration: +sliders.migration.value
  };
}

function getLaborParams() {
  return {
    retireAgeMale: +sliders.retireMale.value, retireAgeFemale: +sliders.retireFemale.value,
    unemploymentRate: +sliders.unemployment.value / 100,
    womenActivity25_45: +sliders.womenActivity.value / 100,
    partTimeRate: +sliders.partTime.value / 100,
    disabMult: +sliders.disability.value, studyShift: +sliders.studyShift.value
  };
}

function requestSimulation() {
  worker.postMessage({
    type: 'simulate', params: getDemoParams(), laborParams: getLaborParams(),
    startPop: anchorData[String(startYear)], startYear, endYear
  });
}

// ─── Render ──────────────────────────────────────────────────────────────────
function renderCurrentYear() {
  if (!snapshots) return;
  const year = +sliders.year.value;
  const snap = snapshots[year];
  if (!snap) return;

  const stData = stateSnapshots ? stateSnapshots[year] : null;
  renderPyramid(pyramidContainer, snap, {
    stateData: stData, hiddenStates,
    width: pyramidContainer.clientWidth - 20,
    height: pyramidContainer.clientHeight - 20
  });

  const totalM = snap.male.reduce((s, v) => s + v, 0);
  const totalF = snap.female.reduce((s, v) => s + v, 0);
  const total = totalM + totalF;

  statEls.totalPop.textContent = formatPopulation(total);
  statEls.malePop.textContent = formatPopulation(totalM);
  statEls.femalePop.textContent = formatPopulation(totalF);

  let children = 0, working = 0, seniors = 0, weightedAge = 0;
  for (let a = 0; a <= 100; a++) {
    const cohort = (snap.male[a] || 0) + (snap.female[a] || 0);
    weightedAge += a * cohort;
    if (a <= 19) children += cohort;
    else if (a <= 64) working += cohort;
    else seniors += cohort;
  }

  statEls.medianAge.textContent = (total > 0 ? (weightedAge / total).toFixed(1) : '—') + ' rokov';
  statEls.children.textContent = formatPopulation(children);
  statEls.working.textContent = formatPopulation(working);
  statEls.seniors.textContent = formatPopulation(seniors);

  if (ratioSeries && ratioSeries[year]) {
    const r = ratioSeries[year];
    const inv = r.ratio > 0 ? (1 / r.ratio) : Infinity;

    ratioEl.textContent = r.ratio > 0 && r.ratio < Infinity
      ? `1 platiteľ na ${inv.toFixed(2)} poberateľa`
      : '—';
    ratioEl.className = 'ratio-value ' + (
      r.ratio >= 2.5 ? 'ratio-green' : r.ratio >= 1.5 ? 'ratio-orange' : 'ratio-red'
    );

    ratioDetailEl.textContent = '';

    statEls.payers.textContent = formatPopulation(r.payers);
    statEls.payersDetail.textContent = `${(r.payers / total * 100).toFixed(1)} % populácie`;
    statEls.recipients.textContent = formatPopulation(r.recipients);
    statEls.recipientsDetail.textContent = `${(r.recipients / total * 100).toFixed(1)} % populácie`;
  }

  yearDisplay.textContent = year;
}

// ─── Events ──────────────────────────────────────────────────────────────────
sliders.year.addEventListener('input', renderCurrentYear);

let debounceTimer = null;
function onParamChange() {
  vals.tfr.textContent = (+sliders.tfr.value).toFixed(1);
  vals.mortMale.textContent = (+sliders.mortMale.value).toFixed(2);
  vals.mortFemale.textContent = (+sliders.mortFemale.value).toFixed(2);
  vals.migration.textContent = (+sliders.migration.value).toFixed(0);
  vals.retireMale.textContent = sliders.retireMale.value;
  vals.retireFemale.textContent = sliders.retireFemale.value;
  vals.unemployment.textContent = (+sliders.unemployment.value).toFixed(1) + '%';
  vals.womenActivity.textContent = sliders.womenActivity.value + '%';
  vals.partTime.textContent = sliders.partTime.value + '%';
  vals.disability.textContent = (+sliders.disability.value).toFixed(1);
  vals.studyShift.textContent = (+sliders.studyShift.value >= 0 ? '+' : '') + (+sliders.studyShift.value).toFixed(1);

  clearTimeout(debounceTimer);
  debounceTimer = setTimeout(requestSimulation, 100);
}

[sliders.tfr, sliders.mortMale, sliders.mortFemale, sliders.migration,
 sliders.retireMale, sliders.retireFemale, sliders.unemployment, sliders.womenActivity,
 sliders.partTime, sliders.disability, sliders.studyShift
].forEach(s => s.addEventListener('input', onParamChange));

// ─── Legend ──────────────────────────────────────────────────────────────────
function refreshLegend() {
  legendContainer.innerHTML = buildLegendHTML(hiddenStates);
  legendContainer.querySelectorAll('.legend-item').forEach(item => {
    item.addEventListener('click', () => {
      const state = item.dataset.state;
      hiddenStates.has(state) ? hiddenStates.delete(state) : hiddenStates.add(state);
      refreshLegend();
      renderCurrentYear();
    });
  });
}

// ─── Reset ───────────────────────────────────────────────────────────────────
$('resetBtn').addEventListener('click', () => {
  for (const [id, val] of Object.entries(DEFAULTS)) $(id).value = val;
  onParamChange();
});

// ─── Collapsible panels ─────────────────────────────────────────────────────
const sliderToggle = $('sliderToggle');
const sliderContent = $('sliderContent');
const sliderPanel = $('sliderPanel');

sliderToggle.addEventListener('click', () => {
  const open = sliderContent.classList.toggle('open');
  sliderPanel.classList.toggle('panel-open', open);
  sliderToggle.innerHTML = open ? '⚙ Nastavenia ▲' : '⚙ Nastavenia ▼';
});

const statsToggle = $('statsToggle');
const statsContent = $('statsContent');

statsToggle.addEventListener('click', () => {
  const open = statsContent.classList.toggle('open');
  statsToggle.innerHTML = open ? '⚙ Štatistiky ▲' : '⚙ Štatistiky ▼';
});

document.querySelectorAll('.slider-section h3').forEach(h3 => {
  h3.addEventListener('click', () => h3.parentElement.classList.toggle('collapsed'));
});

// ─── Tooltip positioning (fixed, viewport-aware) ───────────────────────────
document.querySelectorAll('.slider-tooltip-icon').forEach(icon => {
  function positionTooltip() {
    const tip = icon.querySelector('.tooltip-text');
    if (!tip) return;
    const rect = icon.getBoundingClientRect();
    const vw = window.innerWidth;
    const vh = window.innerHeight;

    tip.style.left = '';
    tip.style.right = '';
    tip.style.top = '';
    tip.style.bottom = '';

    // Try right of icon
    if (rect.right + 12 + 260 < vw) {
      tip.style.left = (rect.right + 8) + 'px';
    } else {
      // Left of icon
      tip.style.right = (vw - rect.left + 8) + 'px';
    }

    // Vertically centered, clamped to viewport
    const tipH = 80;
    let top = rect.top + rect.height / 2 - tipH / 2;
    top = Math.max(8, Math.min(top, vh - tipH - 8));
    tip.style.top = top + 'px';
  }

  icon.addEventListener('mouseenter', positionTooltip);
  icon.addEventListener('focus', positionTooltip);
});

// ─── Init ────────────────────────────────────────────────────────────────────
async function init() {
  try {
    const resp = await fetch('data/anchors.json');
    anchorData = await resp.json();
    for (const [year, pop] of Object.entries(anchorData)) {
      anchorData[year] = { male: Float64Array.from(pop.male), female: Float64Array.from(pop.female) };
    }
    refreshLegend();
    requestSimulation();
  } catch (err) {
    console.error('Init failed:', err);
    pyramidContainer.textContent = 'Chyba pri načítaní dát: ' + err.message;
  }
}

init();
